(5031595, 734089, 42984, '<td valign="top">If just one small part of her face was sharp you''d have a ribbon-winner here</td>', 'If just one small part of her face was sharp you''d have a ribbon-winner here', '2008-10-29 17:02:00.000000', NULL, 1),
(5031627, 734253, 42984, '<td valign="top">I wanted to give this another opoint.  Things that would have counted are; Rotation, getting the horizontal correct (left 1.3deg) and maybe using Thirds a little to move the strong focal centre of the image slightly to the right.  The short fat man framed by the strong gold of the building entrance could make this a serious robbon contender if a large portion of the pavement was gone and the right crop was just behind the girl with the shoulder bag.</td>', 'I wanted to give this another opoint.  Things that would have counted are; Rotation, getting the horizontal correct (left 1.3deg) and maybe using Thirds a little to move the strong focal centre of the image slightly to the right.  The short fat man framed by the strong gold of the building entrance could make this a serious robbon contender if a large portion of the pavement was gone and the right crop was just behind the girl with the shoulder bag.', '2008-10-29 17:14:14.000000', NULL, 1),
(5031629, 734285, 42984, '<td valign="top">Very small, hard to see the strength of the image</td>', 'Very small, hard to see the strength of the image', '2008-10-29 17:15:06.000000', NULL, 1),
