(5031683, 734244, 93756, '<td valign="top">Pretty flower but the grill outside detracts quite a bit.</td>', 'Pretty flower but the grill outside detracts quite a bit.', '2008-10-29 17:57:13.000000', NULL, 1),
(5031687, 734549, 93756, '<td valign="top">I really like it except for the super-saturation. Less is more.</td>', 'I really like it except for the super-saturation. Less is more.', '2008-10-29 18:01:23.000000', NULL, 1),
(5031691, 733737, 93756, '<td valign="top">No wonder my stuff is always late. He needs to speed it up a little to make for a more interesting blur.</td>', 'No wonder my stuff is always late. He needs to speed it up a little to make for a more interesting blur.', '2008-10-29 18:03:26.000000', NULL, 1),
