(5032619, 733662, 65234, '<td valign="top">Looks like a very busy night.  Overall the shot has a bit more of a yellow cast on my screen than I like.</td>', 'Looks like a very busy night.  Overall the shot has a bit more of a yellow cast on my screen than I like.', '2008-10-30 08:49:12.000000', NULL, 1),
(5032626, 734529, 79057, '<td valign="top">Almost unreal ... impressive!</td>', 'Almost unreal ... impressive!', '2008-10-30 08:56:08.000000', NULL, 1),
(5032627, 733941, 83008, '<td valign="top">I don''t really feel like the blurred sky is working to show something wicked coming. Not only because it seems like the sky isn''t coming towards the viewer, but also because the blur just makes it seem... in lack of a better word... cuddely..</td>', 'I don''t really feel like the blurred sky is working to show something wicked coming. Not only because it seems like the sky isn''t coming towards the viewer, but also because the blur just makes it seem... in lack of a better word... cuddely..', '2008-10-30 08:56:26.000000', NULL, 1),
