INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5043994, 734545, 54645, '<td valign="top">Made me laugh. Good job.</td>', 'Made me laugh. Good job.', '2008-11-04 19:03:45.000000', NULL, 1),
(5044053, 733619, 20324, '<td valign="top">I like it , artistic take on the challenge, nice tones and composition. It is really good for the basic challenge, you can "master"it with advanced techniques and sell as a fine art print! Good job!</td>', 'I like it , artistic take on the challenge, nice tones and composition. It is really good for the basic challenge, you can "master"it with advanced techniques and sell as a fine art print! Good job!', '2008-11-04 19:55:59.000000', NULL, 1),
(5044194, 734285, 63633, '<td valign="top">This is really let down by the size of the image. I think yo should make use of the full 640 pixels if possible.</td>', 'This is really let down by the size of the image. I think yo should make use of the full 640 pixels if possible.', '2008-11-04 20:56:08.000000', NULL, 1),
(5044210, 734656, 63633, '<td valign="top">It''s clear from the context that there is motion, but I don''t see the blur. I think your shutter speed was too fast and froze the motion. <br/> <br/>Also, I find the image a bit too grainy for my liking. You could have minimized that by reducing the iso, which also would have decreased the shutter speed, increasing the likelihood of motion blur.</td>', 'It''s clear from the context that there is motion, but I don''t see the blur. I think your shutter speed was too fast and froze the motion.  Also, I find the image a bit too grainy for my liking. You could have minimized that by reducing the iso, which also would have decreased the shutter speed, increasing the likelihood of motion blur.', '2008-11-04 21:04:39.000000', NULL, 1),
(5044211, 734388, 63633, '<td valign="top">I find the tones in this image a bit flat. Greater contrast would have been better in my mind. Cute monkeys!</td>', 'I find the tones in this image a bit flat. Greater contrast would have been better in my mind. Cute monkeys!', '2008-11-04 21:06:04.000000', NULL, 1),
(5044219, 734501, 63633, '<td valign="top">This looks overexposed for my taste.</td>', 'This looks overexposed for my taste.', '2008-11-04 21:13:47.000000', NULL, 1),
(5044230, 734199, 86316, '<td valign="top">Absolutely breathtaking. Probably my favourite of the challenge, the colours are perfect. 10!!!<br/>(edited: congrats!!)<br/><br/><i>Message edited by author 2008-11-05 00:13:09.</i></td>', 'Absolutely breathtaking. Probably my favourite of the challenge, the colours are perfect. 10!!!(edited: congrats!!)', '2008-11-04 21:18:30.000000', '2008-11-05 00:13:09.000000', 1),
